{
  "title": "A Cheaper Day in Reykjavik",
  "summary": "A lighter, thriftier Sunday around Reykjavik with a must-see whale museum, free local stops and budget-friendly meals.",
  "stops": [
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The one big-ticket treat you asked to keep, so we start with the whales before the crowds."
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "Swapped in for the pricey Perlan: a free flea market full of local life and photo-worthy clutter."
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch at Kaffi Loki keeps the budget happy and the rye bread ice cream is a quiet legend."
    },
    {
      "poi_id": "p14",
      "kind": "activity",
      "must_do_id": null,
      "note": "A wander down Laugavegur for window-shopping and street snaps, cheaper than any museum."
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at Hlemmur Mathöll gives everyone a cheap, cheerful choice under one roof."
    }
  ]
}
